const g = await tools.grep({ pattern: "def primeStrip|abbrev primeStrip|def FinitePrimePlace|abbrev FinitePrimePlace|residueCharacteristic|residueNormBase", path: "tmp/sheaf/xif" });
const byP = new Map();
for (const m of g.matches) byP.set(m.path, (byP.get(m.path)||0)+1);
console.log([...byP].slice(0,20).map(([p,c])=>`${p} (${c})`).join("\n"));
console.log(g.matches.slice(0,25).map(m=>`${m.path}:${m.lineNumber}: ${m.line.trim()}`).join("\n"));
", "description": "Find primeStrip and FinitePrimePlace definitions"}

